window.IronholdLocalePatterns=[["Round (\\d+) begins\\.","La manche $1 commence.","$1-раунд басталды."],["Round (\\d+) complete","Manche $1 terminée","$1-раунд аяқталды"],["Release stage (\\d+) output","Libérer la sortie de l’étape $1","$1-саты өнімін беру"],["Stage (\\d+) of (\\d+)","Étape $1 sur $2","$1-саты, барлығы $2"],["(\\d+) total rolls recorded · Last completed roll","$1 lancers enregistrés · Dernier lancer effectué","$1 лақтыру тіркелді · Соңғы аяқталған лақтыру"],["(\\d+) Titans shipped this round\\. (\\d+) approved in total\\.","$1 Titans livrés cette manche. $2 approuvés au total.","Осы раундта $1 Титан жеткізілді. Барлығы $2 мақұлданды."],["(\\d+) Titans shipped in total\\. ([-\\d]+) gold across all guilds\\.","$1 Titans livrés au total. $2 pièces dans toutes les guildes.","Барлығы $1 Титан жеткізілді. Барлық гильдияда $2 алтын."],["Enter a whole number from 1 to (\\d+)\\.","Saisissez un entier de 1 à $1.","1 мен $1 аралығындағы бүтін сан енгізіңіз."],["(\\d+)h due R(\\d+)","$1 h dues en M$2","$1 сағ, мерзімі Р$2"],["(\\d+)h due round (\\d+)","$1 h dues en manche $2","$1 сағ, мерзімі $2-раунд"],["D10 complete","D10 terminé","D10 аяқталды"],["(\\d+)-sided die","Dé à $1 faces","$1 жақты текше"]];
window.IronholdLocaleData=[["Ironhold · Steppe Guilds","Ironhold · Guildes des steppes","Ironhold · Дала гильдиялары"],["Saryarqa Smiths · Сарыарқа","Forgerons de Saryarqa · Сарыарқа","Сарыарқа ұсталары"],["Altai Gearmakers · Алтай","Mécaniciens de l’Altaï · Алтай","Алтай механиктері"],["Zhetysu Armorers · Жетісу","Armuriers de Zhetysu · Жетісу","Жетісу сауытшылары"],["Shanyraq Assembly · Шаңырақ","Assembleurs Shanyraq · Шаңырақ","Шаңырақ құрастырушылары"],["Tulpar Builders · Тұлпар","Constructeurs Tulpar · Тұлпар","Тұлпар жасаушылары"],["Qyran Inspectors · Қыран","Inspecteurs Qyran · Қыран","Қыран бақылаушылары"],["PROCUREMENT · SUPPLIER QUALITY · COORDINATION","ACHATS · QUALITÉ FOURNISSEUR · COORDINATION","САТЫП АЛУ · ЖЕТКІЗУШІ САПАСЫ · ҮЙЛЕСТІРУ"],["Six guilds. One factory. Fifteen rounds to defend the city.","Six guildes. Une usine. Quinze manches pour défendre la cité.","Алты гильдия. Бір зауыт. Қаланы қорғауға он бес раунд."],["Scan to open the game","Scannez pour ouvrir le jeu","Ойынды ашу үшін сканерлеңіз"],["Opens this website. Games on separate devices do not synchronize.","Ouvre ce site. Les parties sur des appareils différents ne sont pas synchronisées.","Осы сайтты ашады. Әртүрлі құрылғыдағы ойындар синхрондалмайды."],["ENTER IRONHOLD","ENTREZ DANS IRONHOLD","IRONHOLD ОЙЫНЫНА КІРУ"],["Choose your classroom role","Choisissez votre rôle en classe","Сыныптағы рөліңізді таңдаңыз"],["The Game Master starts or restores this browser’s session. Guilds then take turns using their own dashboard.","Le maître du jeu démarre ou reprend la partie dans ce navigateur. Les guildes utilisent ensuite leur tableau de bord à tour de rôle.","Ойын жүргізушісі осы браузерде ойынды бастайды немесе жалғастырады. Кейін гильдиялар өз панелін кезекпен пайдаланады."],["Shared-browser role views only. These are display filters, not private accounts. Separate devices do not synchronize; use one instructor-controlled browser.","Vues par rôle dans un navigateur partagé : ce sont des filtres d’affichage, pas des comptes privés. Les appareils ne se synchronisent pas ; utilisez un navigateur contrôlé par l’enseignant.","Рөлдер бір ортақ браузерде көрсетіледі. Бұлар жеке тіркелгілер емес, экран сүзгілері. Құрылғылар синхрондалмайды; оқытушы басқаратын бір браузерді пайдаланыңыз."],["Manage all guilds and reveal results","Gérer toutes les guildes et présenter les résultats","Барлық гильдияны басқару және нәтижелерді көрсету"],["own dashboard","tableau de bord personnel","жеке панель"],["Game Master council keeper","Gardienne du conseil, maître du jeu","Кеңес сақшысы, ойын жүргізушісі"],["Game Master","Maître du jeu","Ойын жүргізушісі"],["Shop 1","Atelier 1","1-цех"],["Shop 2","Atelier 2","2-цех"],["Shop 3","Atelier 3","3-цех"],["Shops 1–3","Ateliers 1–3","1–3-цехтар"],["Subassembly","Sous-assemblage","Торапты құрастыру"],["Final assembly","Assemblage final","Соңғы құрастыру"],["Quality inspection","Contrôle qualité","Сапаны бақылау"],["Quality approved","Qualité approuvée","Сапасы мақұлданған"],["Switch role / hand over screen","Changer de rôle / passer l’écran","Рөлді ауыстыру / экранды беру"],["Showcase all guilds","Présenter toutes les guildes","Барлық гильдияны көрсету"],["Return to Game Master","Retour au maître du jeu","Ойын жүргізушісіне оралу"],["Classroom reveal · all guilds","Présentation en classe · toutes les guildes","Сыныптық талдау · барлық гильдия"],["Read-only debrief. Changing the round below does not change the live game.","Bilan en lecture seule. Changer la manche affichée ne modifie pas la partie.","Тек көруге арналған талдау. Төмендегі раундты ауыстыру ойынды өзгертпейді."],["Recorded round","Manche enregistrée","Тіркелген раунд"],["THE SIEGE OF","LE SIÈGE DE","ҚОРШАУ"],["Six guilds. One common mission.","Six guildes. Une mission commune.","Алты гильдия. Бір ортақ мақсат."],["THE COUNCIL CALLS","LE CONSEIL VOUS APPELLE","КЕҢЕС ШАҚЫРАДЫ"],["Build the Titans.","Construisez les Titans.","Титандарды жасаңыз."],["Keep the guilds alive.","Préservez les guildes.","Гильдияларды сақтап қалыңыз."],["The Iron Tyrant is approaching. Frames, engines and enchanted armor must move through the factory to become battle-ready Titans. Each local decision can help—or hold back—the whole city.","Le Tyran de fer approche. Châssis, moteurs et armures doivent traverser l’usine pour devenir des Titans prêts à défendre la cité. Chaque décision locale peut aider ou freiner toute la chaîne.","Темір тиран жақындап келеді. Қаңқалар, қозғалтқыштар және сауыттар зауыттан өтіп, қаланы қорғайтын Титандарға айналуы тиіс. Әр жергілікті шешім бүкіл тізбекке көмектесуі не кедергі келтіруі мүмкін."],["One instructor controls this screen while the teams discuss decisions. Use virtual dice or enter rolls from physical dice. This is a shared-screen classroom game, not synchronized multiplayer.","Un enseignant contrôle l’écran pendant que les équipes discutent. Lancez les dés virtuels ou saisissez les résultats de dés physiques. Ce jeu pédagogique utilise un écran partagé, sans multijoueur synchronisé.","Командалар шешімдерді талқылағанда экранды бір оқытушы басқарады. Виртуалды текшені лақтырыңыз немесе нақты текшенің нәтижесін енгізіңіз. Бұл — ортақ экрандағы оқу ойыны, синхрондалған көпойыншылық режим емес."],["Begin a session","Commencer une partie","Ойынды бастау"],["Session name","Nom de la partie","Ойын атауы"],["Game mode","Mode de jeu","Ойын режимі"],["Practice · observe output and survival","Entraînement · observer production et survie","Жаттығу · өнім мен өміршеңдікті бақылау"],["Mission · meet an announced shipment target","Mission · atteindre un objectif de livraison","Миссия · жеткізу мақсатына жету"],["Approved Titans required","Titans approuvés requis","Қажетті мақұлданған Титандар"],["Practice is a useful first run. Targets are instructor choices; 30 is a theoretical maximum, not a recommended target. Revised rules 3.0 still need classroom balance testing.","Commencez par l’entraînement. L’enseignant fixe l’objectif ; 30 est un maximum théorique, pas une recommandation. L’équilibrage des règles 3.0 reste à tester en classe.","Алдымен жаттығудан бастаған жөн. Мақсатты оқытушы белгілейді; 30 — ұсынылған мақсат емес, теориялық шек. 3.0 ережелерінің теңгерімі сыныпта тексерілуі тиіс."],["Game Master setup · change starting gold","Réglage enseignant · modifier l’or initial","Жүргізуші баптауы · бастапқы алтынды өзгерту"],["Starting gold for each guild","Or initial de chaque guilde","Әр гильдияның бастапқы алтыны"],["Instructor choice for this new session. Default: 10 gold each. During play, use Game Master gold adjustments.","Choix de l’enseignant pour cette partie. Par défaut : 10 pièces par guilde. Pendant le jeu, utilisez les ajustements du maître du jeu.","Жаңа ойынға арналған оқытушы таңдауы. Әдепкіде әр гильдияға 10 алтын. Ойын кезінде жүргізушінің алтын түзетулерін пайдаланыңыз."],["Open the forge","Ouvrir la forge","Ұстахананы ашу"],["Read the rules first","Lire d’abord les règles","Алдымен ережелерді оқу"],["Meet the six guilds and their supply-chain roles","Découvrir les six guildes et leurs rôles logistiques","Алты гильдия және олардың жеткізу тізбегіндегі рөлдері"],["Factory floor","Atelier de production","Өндіріс алаңы"],["Ledger & history","Registre et historique","Есеп пен тарих"],["Story & rules","Histoire et règles","Оқиға мен ережелер"],["Save game","Enregistrer la partie","Ойынды сақтау"],["Load game","Charger une partie","Ойынды жүктеу"],["Export CSV","Exporter en CSV","CSV экспорттау"],["Undo entry","Annuler la saisie","Енгізуді қайтару"],["New session","Nouvelle partie","Жаңа ойын"],["Resume saved game","Reprendre la partie sauvegardée","Сақталған ойынды жалғастыру"],["The Titan workshop","L’atelier des Titans","Титандар шеберханасы"],["Coordinate the guilds. Keep supplies moving.","Coordonnez les guildes. Assurez la circulation des approvisionnements.","Гильдияларды үйлестіріңіз. Жабдықтар қозғалысын сақтаңыз."],["Choose your session above, or load a saved game.","Choisissez une partie ci-dessus ou chargez une sauvegarde.","Жоғарыдан ойын таңдаңыз немесе сақталған ойынды жүктеңіз."],["THE KEEPER OF THE GUILD TREASURY","LA GARDIENNE DU TRÉSOR DES GUILDES","ГИЛЬДИЯ ҚАЗЫНАСЫНЫҢ САҚШЫСЫ"],["Guild treasury & Game Master","Trésorerie des guildes et maître du jeu","Гильдия қазынасы және ойын жүргізушісі"],["Transfer gold between guilds","Transférer de l’or entre guildes","Гильдиялар арасында алтын аудару"],["Sending guild","Guilde émettrice","Жіберуші гильдия"],["Receiving guild","Guilde bénéficiaire","Алушы гильдия"],["Gold to transfer","Or à transférer","Аударылатын алтын"],["Agreement / reason","Accord / motif","Келісім / себеп"],["For example: shared supplier recovery","Exemple : redressement partagé du fournisseur","Мысалы: жеткізушіні бірлесіп қалпына келтіру"],["Confirm gold transfer","Confirmer le transfert","Алтын аударымын растау"],["Enter Game Master mode","Activer le mode maître du jeu","Жүргізуші режимін ашу"],["Exit Game Master mode","Quitter le mode maître du jeu","Жүргізуші режимінен шығу"],["Instructor controls on this shared screen; no password or separate account.","Commandes enseignant sur cet écran partagé, sans mot de passe ni compte distinct.","Осы ортақ экрандағы оқытушы басқаруы; құпиясөз не жеке тіркелгі жоқ."],["Instructor round exception","Exception de manche de l’enseignant","Оқытушының раунд ерекшелігі"],["Game Master name","Nom du maître du jeu","Ойын жүргізушісінің аты"],["Instructor name","Nom de l’enseignant","Оқытушының аты"],["Exception type","Type d’exception","Ерекшелік түрі"],["Gold grant / penalty · now","Prime / pénalité d’or · immédiate","Алтын беру / айыппұл · қазір"],["Extra downtime · next round","Arrêt supplémentaire · manche suivante","Қосымша тоқтау · келесі раунд"],["Custom round instruction · note only","Consigne personnalisée · note uniquement","Арнайы нұсқау · тек ескерту"],["Affected guild","Guilde concernée","Қатысты гильдия"],["All six guilds","Les six guildes","Барлық алты гильдия"],["Gold change per guild","Variation d’or par guilde","Әр гильдияның алтын өзгерісі"],["Downtime hours per guild","Heures d’arrêt par guilde","Әр гильдияның тоқтау сағаттары"],["Explain the exception","Expliquer l’exception","Ерекшелікті түсіндіріңіз"],["Describe the classroom scenario and why this exception applies","Décrivez la situation et le motif de cette exception","Сыныптық жағдайды және ерекшелік себебін сипаттаңыз"],["Apply and record exception","Appliquer et enregistrer l’exception","Ерекшелікті қолдану және тіркеу"],["Factory network","Réseau de production","Өндіріс желісі"],["Good units in each buffer","Unités conformes dans chaque stock intermédiaire","Әр аралық қордағы жарамды өнім"],["One C1 + one C2 → subassembly. One subassembly + one C3 → Titan. Quality approval counts the shipment once.","Un C1 + un C2 → sous-ensemble. Un sous-ensemble + un C3 → Titan. Le contrôle qualité comptabilise la livraison une seule fois.","Бір C1 + бір C2 → торап. Бір торап + бір C3 → Титан. Сапа мақұлдауы жеткізілімді бір рет қана санайды."],["Latest events","Derniers événements","Соңғы оқиғалар"],["Full record in Ledger & history","Détail dans Registre et historique","Толық жазба «Есеп пен тарихта»"],["The quartermaster’s archive","Les archives de l’intendance","Қамтамасыз ету мұрағаты"],["Every roll, every decision, every gold piece.","Chaque lancer, chaque décision, chaque pièce d’or.","Әр лақтыру, әр шешім, әр алтын."],["The council of six","Le conseil des six","Алтылық кеңесі"],["Learn the mission. Agree on the rules.","Découvrez la mission. Accordez-vous sur les règles.","Миссияны біліңіз. Ережелерді келісіңіз."],["Guild ledger","Registre des guildes","Гильдия есебі"],["Repairs are paid when issued. Hours served are not charged again. Only Quality output is a factory shipment.","Les réparations sont payées à l’émission du ticket. Les heures effectuées ne sont pas refacturées. Seules les sorties du contrôle qualité sont des livraisons de l’usine.","Жөндеу құны тапсырма берілгенде төленеді. Өтелген сағаттарға қайта ақы алынбайды. Тек сапа бақылауынан өткен өнім зауыт жеткізілімі болып саналады."],["Gold transfers & adjustments","Transferts et ajustements d’or","Алтын аударымдары мен түзетулері"],["Cash movements (net)","Mouvements de trésorerie nets","Таза ақша қозғалысы"],["Repair costs","Coûts de réparation","Жөндеу шығындары"],["Transferred units","Unités transférées","Берілген өнім"],["Outstanding hours","Heures restantes","Қалған сағаттар"],["Round results","Résultats par manche","Раунд нәтижелері"],["Shipped this round","Livré cette manche","Осы раундта жеткізілді"],["Cumulative shipped","Livraisons cumulées","Жиынтық жеткізілім"],["Factory gold at round end","Or de l’usine en fin de manche","Раунд соңындағы зауыт алтыны"],["Repair tickets","Tickets de réparation","Жөндеу тапсырмалары"],["Complete event history","Historique complet des événements","Оқиғалардың толық тарихы"],["Every dice outcome, reroll, decision, transfer and charge. Saving preserves this history through replay.","Chaque résultat, relance, décision, transfert et charge. La sauvegarde conserve cet historique par rejeu.","Әр нәтиже, қайта лақтыру, шешім, аударым және шығын. Сақтау бұл тарихты қайта орындау арқылы қалпына келтіреді."],["Start a session to view the ledger.","Démarrez une partie pour voir le registre.","Есепті көру үшін ойынды бастаңыз."],["Guild transfer","Transfert entre guildes","Гильдия аударымы"],["Counterparty","Contrepartie","Қарсы тарап"],["Charged team","Équipe facturée","Төлем жүктелген команда"],["Issued","Émis","Берілген"],["Reason","Motif","Себеп"],["Change","Variation","Өзгеріс"],["Type","Type","Түрі"],["Due","Échéance","Мерзімі"],["None","Aucun","Жоқ"],["Gold","Or","Алтын"],["Guild","Guilde","Гильдия"],["Round","Manche","Раунд"],["Hours","Heures","Сағат"],["Settlement","Règlement final","Қорытынды есеп"],["Final settlement","Règlement final","Қорытынды есеп"],["Production roll","Lancer de production","Өндіріс текшесі"],["Procurement exception roll","Lancer d’incident d’approvisionnement","Жабдықтау оқиғасының текшесі"],["Find an applicable solution","Trouver une solution applicable","Қолайлы шешім табу"],["Identify the rework origin","Identifier l’origine de la reprise","Қайта өңдеу себебінің көзін анықтау"],["Resolve deferred analysis","Résoudre l’analyse différée","Кейінге қалған талдауды шешу"],["1–3: one-unit base capacity. 4–6: two-unit base capacity. Inputs and repairs can reduce the actual transfer.","1–3 : capacité de base de 1 unité. 4–6 : 2 unités. Les composants disponibles et les réparations peuvent réduire la sortie réelle.","1–3: негізгі қуат 1 өнім. 4–6: 2 өнім. Кіріс бөлшектер мен жөндеу нақты берілетін өнімді азайтуы мүмкін."],["Roll D10. Odd or inapplicable outcomes require another roll. A physical 0 means 10.","Lancez le D10. Un résultat impair ou inapplicable impose une relance. Le 0 d’un dé physique signifie 10.","D10 лақтырыңыз. Тақ немесе жарамсыз нәтиже болса, қайта лақтырыңыз. Нақты текшедегі 0 саны 10 дегенді білдіреді."],["Other results reroll without changing the procurement response.","Les autres résultats sont relancés sans modifier la réponse d’achat.","Басқа нәтижелерде сатып алу әрекетін өзгертпей қайта лақтырыңыз."],["Valid faces:","Faces valides :","Жарамды жақтар:"],["1–3: Shop 1. 4–6: Shop 2. The origin pays 2 gold and repairs next round.","1–3 : atelier 1. 4–6 : atelier 2. L’origine paie 2 pièces et répare à la manche suivante.","1–3: 1-цех. 4–6: 2-цех. Себеп көзі 2 алтын төлеп, келесі раундта жөндейді."],["1–3: Subassembly. 4–6: Shop 3. The origin pays 2 gold and repairs next round.","1–3 : sous-assemblage. 4–6 : atelier 3. L’origine paie 2 pièces et répare à la manche suivante.","1–3: торапты құрастыру. 4–6: 3-цех. Себеп көзі 2 алтын төлеп, келесі раундта жөндейді."],["1–2: close at no cost. 3–4: 4h / 1 gold. 5–6: 8h / 2 gold.","1–2 : clôture sans frais. 3–4 : 4 h / 1 pièce. 5–6 : 8 h / 2 pièces.","1–2: шығынсыз жабу. 3–4: 4 сағ / 1 алтын. 5–6: 8 сағ / 2 алтын."],["No more production occurs.","Il n’y a plus de production.","Енді өндіріс болмайды."],["Repair hours are served before this round’s production.","Les heures de réparation sont effectuées avant la production de cette manche.","Жөндеу сағаттары осы раунд өндірісіне дейін өтеледі."],["Review the roll above","Examiner le résultat ci-dessus","Жоғарыдағы нәтижені қараңыз"],["Discuss the result with the team, then continue to the next decision.","Discutez du résultat en équipe, puis passez à la décision suivante.","Нәтижені командамен талқылап, келесі шешімге өтіңіз."],["Continue to separate D10 roll","Passer au lancer D10 séparé","Жеке D10 лақтыруына өту"],["Continue to next action","Passer à l’action suivante","Келесі әрекетке өту"],["The session is complete","La partie est terminée","Ойын аяқталды"],["Review the factory result, compare guild decisions and export your ledger.","Examinez le résultat de l’usine, comparez les décisions et exportez le registre.","Зауыт нәтижесін қарап, гильдия шешімдерін салыстырыңыз және есепті экспорттаңыз."],["Review the ledger","Consulter le registre","Есепті қарау"],["Physical die result","Résultat du dé physique","Нақты текшенің нәтижесі"],["Record roll","Enregistrer le lancer","Нәтижені тіркеу"],["Every die outcome is recorded in the history.","Chaque résultat de dé est enregistré dans l’historique.","Әр текше нәтижесі тарихқа жазылады."],["Last roll:","Dernier lancer :","Соңғы лақтыру:"],["How will you respond?","Quelle sera votre réponse ?","Қандай әрекет жасайсыз?"],["Partial capacity: 1. Cause:","Capacité partielle : 1. Cause :","Ішінара қуат: 1. Себеп:"],["Discuss the downstream effect before choosing.","Discutez de l’effet en aval avant de choisir.","Таңдамас бұрын келесі сатыларға әсерін талқылаңыз."],["Planned supplier corrective action","Action corrective fournisseur planifiée","Жеткізушінің жоспарлы түзету әрекеті"],["Supplier risk review","Évaluation du risque fournisseur","Жеткізуші тәуекелін бағалау"],["Quality hold · immediate corrective action","Blocage qualité · action corrective immédiate","Сапа бойынша тоқтату · шұғыл түзету әрекеті"],["Quality hold · immediate action","Blocage qualité · action immédiate","Сапа бойынша тоқтату · шұғыл әрекет"],["Choose a solution and pay now. Serve repair hours next round.","Choisissez une solution et payez maintenant. Réparez à la manche suivante.","Шешім таңдап, қазір төлеңіз. Жөндеуді келесі раундта орындаңыз."],["Resolve a 0h, 4h or 8h outcome next round.","Résolvez un résultat de 0, 4 ou 8 h à la manche suivante.","Келесі раундта 0, 4 немесе 8 сағаттық нәтижені шешіңіз."],["Choose a solution and serve repair hours before releasing output.","Choisissez une solution et réparez avant de libérer la production.","Шешім таңдап, өнімді бермес бұрын жөндеу сағаттарын өтеңіз."],["Keep or change the vendor?","Conserver ou changer le fournisseur ?","Жеткізушіні қалдыру ма, ауыстыру ма?"],["A majority for change charges each shop 2 gold and schedules 8 repair hours next round.","Une majorité pour changer impose 2 pièces et 8 heures de réparation à chaque atelier à la manche suivante.","Ауыстыруға көпшілік дауыс берсе, әр цех 2 алтын төлеп, келесі раундта 8 сағат жөндейді."],["Choose a vote","Choisir un vote","Дауыс таңдау"],["Keep vendor","Conserver le fournisseur","Жеткізушіні қалдыру"],["Change vendor","Changer de fournisseur","Жеткізушіні ауыстыру"],["Record the three votes","Enregistrer les trois votes","Үш дауысты тіркеу"],["Transfer good units","Transférer les unités conformes","Жарамды өнімді беру"],["Production complete","Production terminée","Өндіріс аяқталды"],["Pause for the cycle debrief","Pause pour le bilan du cycle","Циклді талдау үзілісі"],["Discuss before continuing","Discuter avant de continuer","Жалғастырмас бұрын талқылаңыз"],["Which shortage or repair constrained the factory?","Quelle pénurie ou réparation a limité l’usine ?","Қандай тапшылық не жөндеу зауытты шектеді?"],["Did saving local gold help the common mission?","L’économie d’or locale a-t-elle aidé la mission commune ?","Жергілікті алтынды үнемдеу ортақ мақсатқа көмектесті ме?"],["What will your team do differently?","Que changera votre équipe ?","Командаңыз нені басқаша жасайды?"],["Final settlement resolves any deferred analysis before scoring. Already-paid outstanding repairs are not charged again.","Le règlement final résout les analyses différées avant le bilan. Les réparations déjà payées ne sont pas refacturées.","Қорытынды есеп ұпайды анықтамас бұрын кейінге қалған талдауды шешеді. Төленген жөндеуге қайта ақы алынбайды."],["Cash, inventories, vendor protection and queued repairs carry forward.","Trésorerie, stocks, protection fournisseur et réparations en attente sont reportés.","Ақша, қорлар, жеткізуші қорғанысы және кезектегі жөндеу келесі раундқа өтеді."],["Settle outstanding analysis","Régler les analyses restantes","Қалған талдауды аяқтау"],["Begin round","Commencer la manche","Раундты бастау"],["Supply clear","Flux normal","Жабдықтау қалыпты"],["Quality hold","Blocage qualité","Сапа бойынша тоқтату"],["Planned action","Action planifiée","Жоспарлы әрекет"],["Risk review","Évaluation du risque","Тәуекелді бағалау"],["Supplier review","Évaluation fournisseur","Жеткізушіні бағалау"],["Corrective work","Travaux correctifs","Түзету жұмыстары"],["Awaiting inputs","En attente de composants","Бөлшектер күтілуде"],["Awaiting turn","En attente du tour","Кезек күтілуде"],["Approved Titans","Titans approuvés","Мақұлданған Титандар"],["Practice · no target victory","Entraînement · sans victoire sur objectif","Жаттығу · мақсат жеңісі жоқ"],["All guilds must also survive","Toutes les guildes doivent aussi survivre","Барлық гильдия да сақталуы тиіс"],["Total gold · initial baseline below","Or total · montant initial ci-dessous","Жалпы алтын · төменде бастапқы мөлшер"],["Every individual guild must stay above 0","Chaque guilde doit rester au-dessus de 0","Әр гильдияда 0-ден артық алтын болуы тиіс"],["Outstanding work","Travaux restants","Қалған жұмыс"],["C1 waiting","C1 en attente","C1 күтуде"],["C2 waiting","C2 en attente","C2 күтуде"],["C3 waiting","C3 en attente","C3 күтуде"],["awaiting inspection","en attente de contrôle","тексеру күтілуде"],["Titans shipped","Titans livrés","Жеткізілген Титандар"],["No active protection. A third occurrence forces a change.","Aucune protection active. Le troisième incident impose un changement.","Белсенді қорғаныс жоқ. Үшінші оқиға ауыстыруды міндеттейді."],["Analysis is pending.","Analyse en attente.","Талдау күтілуде."],["Ironhold is defended.","Ironhold est défendue.","Ironhold қорғалды."],["The factory has stopped.","L’usine s’est arrêtée.","Зауыт тоқтады."],["The shipment target was missed.","L’objectif de livraison n’a pas été atteint.","Жеткізу мақсатына жетпеді."],["Practice session complete.","Entraînement terminé.","Жаттығу аяқталды."],["Review output and survival; practice mode awards no target victory.","Examinez production et survie ; l’entraînement n’attribue pas de victoire sur objectif.","Өнім мен өміршеңдікті қараңыз; жаттығу режимінде мақсат жеңісі берілмейді."],["No Master Guild is awarded when the factory fails.","Aucun titre de guilde maîtresse en cas d’échec de l’usine.","Зауыт сәтсіз болса, үздік гильдия атағы берілмейді."],["This game has ended. Use Undo for an entry error or start a new session.","Cette partie est terminée. Annulez une erreur de saisie ou commencez une nouvelle partie.","Бұл ойын аяқталды. Енгізу қатесін қайтарыңыз немесе жаңа ойын бастаңыз."],["Positive adds gold; negative deducts gold. Applied per selected guild. A balance of zero or less ends the game.","Un montant positif ajoute de l’or, un montant négatif en retire, pour chaque guilde sélectionnée. Un solde nul ou négatif termine la partie.","Оң сан алтын қосады, теріс сан шегереді. Әр таңдалған гильдияға қолданылады. Қалдық нөлге не одан төмен түссе, ойын аяқталады."],["No gold charge. Adds queued downtime from next round; existing work is retained. Available in rounds 1–14 only.","Sans coût en or. Ajoute un arrêt à partir de la manche suivante ; les travaux existants restent en attente. Disponible uniquement aux manches 1–14.","Алтын алынбайды. Келесі раундтан бастап тоқтау қосылады; бар жұмыс сақталады. Тек 1–14-раундтарда қолжетімді."],["Record an instructor instruction for this round. A note does not automatically change dice, production, stock or costs.","Enregistrez une consigne pour cette manche. Une note ne modifie pas automatiquement les dés, la production, les stocks ou les coûts.","Осы раундқа оқытушы нұсқауын жазыңыз. Ескерту текшені, өндірісті, қорды не шығынды автоматты өзгертпейді."],["Autosaved in this browser. Download a game save before leaving or changing devices.","Sauvegarde automatique dans ce navigateur. Téléchargez une sauvegarde avant de quitter ou de changer d’appareil.","Осы браузерде автоматты сақталды. Шықпас бұрын не құрылғыны ауыстырмас бұрын сақтық көшірмені жүктеп алыңыз."],["Browser storage is unavailable. Use Save game to keep your progress.","Le stockage du navigateur est indisponible. Utilisez Enregistrer la partie.","Браузер жады қолжетімсіз. Ойынды сақтау арқылы ілгерілеуді сақтаңыз."],["This shared-browser view filters the display. It is not secure, separate-device multiplayer.","Cette vue filtre l’affichage dans un navigateur partagé. Ce n’est pas un multijoueur sécurisé sur plusieurs appareils.","Бұл көрініс ортақ браузердегі экранды сүзеді. Бұл бірнеше құрылғыдағы қорғалған көпойыншылық режим емес."],["Your gold","Votre or","Сіздің алтыныңыз"],["Your total units","Vos unités cumulées","Сіздің жалпы өніміңіз"],["Your queued downtime","Votre arrêt en attente","Сіздің кезектегі тоқтауыңыз"],["Your status","Votre état","Сіздің күйіңіз"],["Roll dice","Lancer les dés","Текшелерді лақтыру"],["Guild stock & history","Stocks et historique de la guilde","Гильдия қоры мен тарихы"],["Your dice & decisions","Vos dés et décisions","Сіздің текшелеріңіз бен шешімдеріңіз"],["Only the die required by the current rule is available on your turn. Review each result before continuing.","À votre tour, seul le dé requis est disponible. Examinez chaque résultat avant de continuer.","Өз кезегіңізде тек ереже талап ететін текше қолжетімді. Жалғастырмас бұрын әр нәтижені қараңыз."],["Your stock & work","Vos stocks et travaux","Сіздің қорыңыз бен жұмысыңыз"],["Your gold transfers","Vos transferts d’or","Сіздің алтын аударымдарыңыз"],["Gold to send","Or à envoyer","Жіберілетін алтын"],["You must retain at least 1 gold.","Vous devez conserver au moins 1 pièce d’or.","Кемінде 1 алтын қалдыруыңыз керек."],["Send gold","Envoyer l’or","Алтын жіберу"],["No transfers or adjustments.","Aucun transfert ni ajustement.","Аударым не түзету жоқ."],["Your event history","Votre historique","Сіздің оқиғалар тарихыңыз"],["No events yet.","Aucun événement pour l’instant.","Әзірге оқиға жоқ."],["Read the common game rules","Lire les règles communes","Ортақ ойын ережелерін оқу"],["Review complete · continue","Examen terminé · continuer","Нәтиже қаралды · жалғастыру"],["Choose your procurement response.","Choisissez votre réponse d’achat.","Сатып алу әрекетін таңдаңыз."],["Waiting for the Game Master or another guild. Your information remains below.","En attente du maître du jeu ou d’une autre guilde. Vos informations restent ci-dessous.","Ойын жүргізушісі не басқа гильдия күтілуде. Ақпаратыңыз төменде қалады."],["The session has ended. The Game Master can showcase the full factory results.","La partie est terminée. Le maître du jeu peut présenter les résultats complets.","Ойын аяқталды. Жүргізуші зауыттың толық нәтижелерін көрсете алады."],["The Game Master is collecting supplier votes.","Le maître du jeu recueille les votes sur le fournisseur.","Жүргізуші жеткізуші туралы дауыстарды жинауда."],["Tell the instructor whether your shop votes to keep or change the supplier.","Dites à l’enseignant si votre atelier vote pour conserver ou changer le fournisseur.","Оқытушыға цехыңыз жеткізушіні қалдыруға ма, ауыстыруға ма дауыс беретінін айтыңыз."],["Wait for the shop vote to finish.","Attendez la fin du vote des ateliers.","Цехтардың дауыс беруінің аяқталуын күтіңіз."],["Raw material input: available subject to supplier events","Matières premières : disponibles sous réserve des incidents fournisseur","Шикізат кірісі: жеткізуші оқиғаларына байланысты қолжетімді"],["Your output buffer:","Votre stock de sortie :","Сіздің шығыс қорыңыз:"],["Your approved shipments:","Vos livraisons approuvées :","Сіздің мақұлданған жеткізілімдеріңіз:"],["No queued downtime.","Aucun arrêt en attente.","Кезектегі тоқтау жоқ."],["D10 required for this production roll.","D10 requis pour ce lancer de production.","Осы өндіріс нәтижесіне D10 қажет."],["No D10 required for this production roll.","Aucun D10 requis pour ce lancer de production.","Осы өндіріс нәтижесіне D10 қажет емес."],["D10 required for this roll · partial capacity: 1 unit. Identify the procurement exception.","D10 requis · capacité partielle : 1 unité. Identifiez l’incident d’approvisionnement.","D10 қажет · ішінара қуат: 1 өнім. Жабдықтау оқиғасын анықтаңыз."],["No D10 required for this roll · full base capacity: 2 units. Actual transfer still depends on inputs and corrective work.","D10 non requis · capacité de base complète : 2 unités. Le transfert dépend encore des composants et des travaux correctifs.","D10 қажет емес · толық негізгі қуат: 2 өнім. Нақты беру бөлшектер мен түзету жұмыстарына байланысты."],["Roll D10 again · this result is odd or does not apply to this team. No charge.","Relancez le D10 · résultat impair ou inapplicable à cette équipe. Sans frais.","D10 қайта лақтырыңыз · нәтиже тақ не осы командаға жарамсыз. Ақы алынбайды."],["Follow the response below.","Suivez la réponse ci-dessous.","Төмендегі әрекетті орындаңыз."],["This result does not apply; roll again.","Ce résultat ne s’applique pas ; relancez.","Бұл нәтиже жарамсыз; қайта лақтырыңыз."],["Roll recorded. Follow the next action below.","Lancer enregistré. Suivez l’action suivante ci-dessous.","Нәтиже тіркелді. Төмендегі келесі әрекетті орындаңыз."],["The Game Master must start a session in this browser first.","Le maître du jeu doit d’abord démarrer une partie dans ce navigateur.","Алдымен жүргізуші осы браузерде ойынды бастауы тиіс."],["Choose the next role. The game is retained in this browser.","Choisissez le rôle suivant. La partie reste dans ce navigateur.","Келесі рөлді таңдаңыз. Ойын осы браузерде сақталады."],["Machine failure","Panne de machine","Машинаның ақауы"],["Machine misalignment","Désalignement de machine","Машинаның тураланбауы"],["Machine breakdown","Panne majeure de machine","Машинаның күрделі бұзылуы"],["Defective part","Pièce défectueuse","Ақаулы бөлшек"],["Defective raw material","Matière première défectueuse","Ақаулы шикізат"],["Stop and investigate","Arrêter et examiner","Тоқтатып зерттеу"],["Root cause analysis","Analyse de cause racine","Түпкі себепті талдау"],["Software / parts fix","Correction logicielle / de pièce","Бағдарламаны / бөлшекті түзету"],["Rework","Reprise","Қайта өңдеу"],["Voluntary vendor change","Changement volontaire de fournisseur","Жеткізушіні ерікті ауыстыру"],["Forced vendor change","Changement imposé de fournisseur","Жеткізушіні мәжбүрлі ауыстыру"],["Deferred analysis","Analyse différée","Кейінге қалған талдау"],["Procurement lab · learn from each round","Atelier achats · apprendre de chaque manche","Сатып алу зертханасы · әр раундтан үйрену"],["These worked calculations use your recorded game. Gold is a teaching currency and a round is a planning period. The model omits purchase prices, revenue, freight, inventory holding costs and customer due dates: its charges are not a full total cost of ownership, profit or on-time delivery measure.","Ces calculs utilisent votre partie enregistrée. L’or est une monnaie pédagogique et une manche une période de planification. Le modèle omet prix d’achat, revenus, transport, coût de stockage et échéances clients : ses charges ne mesurent ni le coût total de possession, ni le bénéfice, ni la ponctualité des livraisons.","Бұл есептеулер тіркелген ойыныңызды қолданады. Алтын — оқу валютасы, раунд — жоспарлау кезеңі. Модель сатып алу бағасын, табысты, тасымалды, қор сақтау құнын және клиент мерзімдерін қамтымайды: оның шығыны толық иелену құнын, пайданы не уақытылы жеткізуді өлшемейді."],["recorded so far","enregistré jusqu’ici","әзірге тіркелген"],["recorded end of round","fin de manche enregistrée","раунд соңы тіркелген"],["completed","terminée","аяқталған"],["shipped","livré(s)","жеткізілді"],["1. Flow, capacity and component availability","1. Flux, capacité et disponibilité des composants","1. Ағын, қуат және бөлшектердің қолжетімділігі"],["One subassembly needs 1 Component 1 + 1 Component 2; one final unit needs 1 subassembly + 1 Component 3. Quality inspection turns an uninspected unit into a shipment. Count only those shipments as customer output, not the sum of all guild transfers.","Un sous-ensemble exige 1 composant 1 + 1 composant 2 ; une unité finale exige 1 sous-ensemble + 1 composant 3. Le contrôle qualité transforme une unité non contrôlée en livraison. Comptez ces livraisons, et non la somme des transferts de toutes les guildes, comme sortie client.","Бір торапқа 1 Бөлшек 1 + 1 Бөлшек 2 қажет; бір соңғы өнімге 1 торап + 1 Бөлшек 3 қажет. Сапа бақылауы тексерілмеген өнімді жеткізілімге айналдырады. Клиентке берілген өнім ретінде барлық гильдия аударымдарын емес, тек осы жеткізілімдерді санаңыз."],["Worked output calculation","Calcul détaillé de la sortie","Өнімнің толық есебі"],["Procurement interpretation","Interprétation pour les achats","Сатып алу тұрғысынан түсіндіру"],["Awaiting production decision.","Décision de production en attente.","Өндіріс шешімі күтілуде."],["Available capacity","Capacité disponible","Қолжетімді қуат"],["base units","unités de base","негізгі өнім"],["quality hold","blocage qualité","сапа бойынша тоқтату"],["Input availability:","Composants disponibles :","Кіріс қолжетімділігі:"],["raw inputs not quantity-limited in this model","matières premières sans limite quantitative dans ce modèle","бұл модельде шикізат саны шектелмейді"],["Released output","Sortie libérée","Берілген өнім"],["complete input sets","jeux complets de composants","толық кіріс жиынтықтары"],["unlimited inputs","entrées illimitées","шексіз кірістер"],["Output not released yet; final input availability and output remain pending.","Sortie non libérée ; disponibilité finale des composants et sortie encore en attente.","Өнім әлі берілген жоқ; соңғы кіріс қолжетімділігі мен өнім күтілуде."],["Containment prevents suspect output moving downstream; inputs remain available.","Le confinement empêche une sortie suspecte d’avancer ; les composants restent disponibles.","Оқшаулау күмәнді өнімнің келесі сатыға өтуін тоқтатады; кіріс бөлшектер сақталады."],["Missing input sets constrain output. More local capacity alone would not solve this shortage.","Le manque de composants complets limite la sortie. Augmenter seulement la capacité locale ne résoudrait pas cette pénurie.","Толық кіріс жиынтығының жетіспеуі өнімді шектейді. Тек жергілікті қуатты арттыру тапшылықты шешпейді."],["Corrective work consumes productive time. Procurement must coordinate recovery with downstream demand.","Les travaux correctifs consomment du temps productif. Les achats doivent coordonner le rétablissement avec la demande en aval.","Түзету жұмыстары өндірістік уақытты жұмсайды. Сатып алу қызметі қалпына келуді келесі сатылар сұранысымен үйлестіруі тиіс."],["Match replenishment to downstream consumption; local output is not automatically a customer shipment.","Adaptez le réapprovisionnement à la consommation en aval ; une sortie locale n’est pas automatiquement une livraison client.","Толықтыруды келесі саты тұтынуына сәйкестендіріңіз; жергілікті өнім автоматты түрде клиент жеткізілімі емес."],["Wait for the recorded decision before interpreting the result.","Attendez la décision enregistrée avant d’interpréter le résultat.","Нәтижені түсіндіру үшін тіркелген шешімді күтіңіз."],["Production D6: 1–3 gives 1 base unit and requires a D10 exception; 4–6 gives 2 base units. Maintenance and missing-input turns follow their own rules and may skip dice. A reroll identifies an applicable event; it does not create an extra unit or charge.","D6 de production : 1–3 donne 1 unité de base et impose un D10 ; 4–6 donne 2 unités. Réparation et manque de composants suivent leurs propres règles et peuvent supprimer les lancers. Une relance identifie un incident applicable, sans unité ni coût supplémentaire.","Өндірістік D6: 1–3 негізгі 1 өнім беріп, D10 оқиғасын талап етеді; 4–6 негізгі 2 өнім береді. Жөндеу мен кіріс тапшылығының өз ережесі бар, текше өткізілмеуі мүмкін. Қайта лақтыру жарамды оқиғаны анықтайды, қосымша өнім не шығын туғызбайды."],["2. Inventory balance · where work accumulates","2. Bilan des stocks · où le travail s’accumule","2. Қор балансы · жұмыс қайда жиналады"],["Opening + received − consumed = closing so far","Initial + reçu − consommé = solde actuel","Бастапқы + алынған − жұмсалған = қазіргі қалдық"],["Growing buffers signal work waiting between stages. Ask whether the next stage lacks its matching component, is under a quality hold, or is serving repair hours. Buffer quantities are units, not inventory value.","Des stocks croissants signalent une attente entre étapes. L’étape suivante manque-t-elle d’un composant complémentaire, subit-elle un blocage qualité ou des réparations ? Les stocks sont des quantités, pas des valeurs monétaires.","Өсіп жатқан аралық қорлар сатылар арасында жұмыс күтіп тұрғанын көрсетеді. Келесі сатыға жұп бөлшек жетпей ме, сапа бойынша тоқтаған ба, әлде жөнделіп жатыр ма? Қор саны — өнім бірлігі, ақша құны емес."],["3. Cost of poor quality and liquidity","3. Coût de non-qualité et liquidité","3. Сапасыздық құны және өтімділік"],["Opening gold + net transfers + instructor adjustments − new charges = closing gold","Or initial + transferts nets + ajustements enseignant − nouvelles charges = or final","Бастапқы алтын + таза аударым + оқытушы түзетуі − жаңа шығын = соңғы алтын"],["Transfers between guilds cancel across the factory. Repair tickets are charged when issued; serving their hours later does not charge gold again.","Les transferts entre guildes s’annulent au niveau de l’usine. Les tickets sont facturés à l’émission ; effectuer ensuite les heures ne coûte pas de nouvel or.","Гильдия аударымдары зауыт бойынша өзара жойылады. Жөндеу тапсырмасы берілгенде төленеді; сағатын кейін өтеу қайта алтын алмайды."],["New charges per shipment this round","Nouvelles charges par livraison cette manche","Осы раундтағы бір жеткізілімге жаңа шығын"],["undefined (no shipments)","non défini (aucune livraison)","анықталмаған (жеткізілім жоқ)"],["gold/shipment","or/livraison","алтын/жеткізілім"],["This is a period indicator, not a unit production cost: today’s charges may fund future recovery, while today’s work may use earlier repairs.","C’est un indicateur de période, pas un coût de production unitaire : les charges actuelles peuvent financer un rétablissement futur, tandis que la production actuelle peut bénéficier de réparations antérieures.","Бұл — кезең көрсеткіші, өнім бірлігінің өндірістік құны емес: бүгінгі шығын болашақ қалпына келуді қаржыландыруы мүмкін, ал бүгінгі жұмыс бұрынғы жөндеуге сүйенуі мүмкін."],["4. Negotiation and recorded outcomes","4. Négociation et résultats enregistrés","4. Келіссөздер және тіркелген нәтижелер"],["Stated reason:","Motif déclaré :","Көрсетілген себеп:"],["Factory cash effect","Effet sur la trésorerie de l’usine","Зауыт ақшасына әсері"],["Discuss what recovery commitment or delivery promise should accompany the support. The transfer itself does not change capacity, stock or a supplier contract.","Discutez de l’engagement de rétablissement ou de livraison à associer au soutien. Le transfert seul ne modifie ni capacité, ni stocks, ni contrat fournisseur.","Қолдаумен бірге қандай қалпына келтіру міндеттемесі не жеткізу уәдесі болуы керегін талқылаңыз. Аударымның өзі қуатты, қорды не жеткізуші шартын өзгертпейді."],["No gold transfer recorded this round. Discuss whether support for a cash-constrained guild would protect the whole chain, and what commitment the supporting guild would request.","Aucun transfert cette manche. Un soutien à une guilde à court de trésorerie protégerait-il toute la chaîne ? Quel engagement demanderait la guilde qui aide ?","Осы раундта алтын аударымы жоқ. Ақшасы аз гильдияны қолдау бүкіл тізбекті қорғай ма және көмек беруші қандай міндеттеме сұрар еді?"],["No corrective-action or supplier decision recorded yet.","Aucune décision corrective ou fournisseur enregistrée pour l’instant.","Әзірге түзету не жеткізуші шешімі тіркелмеген."],["Supplier-switch trade-off:","Arbitrage du changement fournisseur :","Жеткізуші ауыстырудың салыстырмасы:"],["a voluntary change charges 3 shops × 2 gold = 6 gold and creates 3 × 8h = 24 repair hours. A forced change charges 3 × 7 = 21 gold and creates 3 × 32h = 96 hours. The difference is 15 gold and 72 hours of queued work. This comparison does not prove switching now is best: weigh future defects, remaining rounds and the current supplier occurrence count. Protection lasts through the switch round + 5 and only blocks the defective-raw-material event.","un changement volontaire coûte 3 ateliers × 2 or = 6 or et crée 3 × 8 h = 24 heures de réparation. Un changement imposé coûte 3 × 7 = 21 or et crée 3 × 32 h = 96 heures. Écart : 15 or et 72 heures en attente. Cela ne prouve pas qu’il faut changer maintenant : pesez défauts futurs, manches restantes et compteur actuel. La protection dure jusqu’à la manche du changement + 5 et bloque seulement l’incident de matière première défectueuse.","ерікті ауыстыру 3 цех × 2 алтын = 6 алтын тұрады және 3 × 8 сағ = 24 жөндеу сағатын қосады. Мәжбүрлі ауыстыру 3 × 7 = 21 алтын тұрады және 3 × 32 сағ = 96 сағат қосады. Айырмасы — 15 алтын және кезектегі 72 сағат. Бұл қазір ауыстыру ең жақсы дегенді білдірмейді: болашақ ақауларды, қалған раундтарды және жеткізуші оқиғалары санын бағалаңыз. Қорғаныс ауыстыру раунды + 5-ке дейін созылып, тек ақаулы шикізат оқиғасын бөгейді."],["5. Explain the procurement choice","5. Expliquer le choix d’achat","5. Сатып алу таңдауын түсіндіру"],["Planned corrective action:","Action corrective planifiée :","Жоспарлы түзету әрекеті:"],["pay when the ticket is issued, with downtime due next round.","payez à l’émission du ticket, avec arrêt dû à la manche suivante.","тапсырма берілгенде төлеңіз, тоқтау келесі раундта өтеледі."],["contain the problem now; current output may fall.","confinez le problème maintenant ; la sortie actuelle peut diminuer.","мәселені қазір оқшаулаңыз; ағымдағы өнім төмендеуі мүмкін."],["defer uncertainty to a later D6. Its 0h/0 gold, 4h/1 gold and 8h/2 gold outcomes each have probability 1/3, so expected cost = (0 + 1 + 2) ÷ 3 = 1 gold and expected repair time = (0 + 4 + 8) ÷ 3 = 4h. These are averages, not promises for the next roll.","reportez l’incertitude à un D6 ultérieur. Les résultats 0 h/0 or, 4 h/1 or et 8 h/2 or ont chacun une probabilité de 1/3. Coût espéré = (0 + 1 + 2) ÷ 3 = 1 or ; durée espérée = (0 + 4 + 8) ÷ 3 = 4 h. Ce sont des moyennes, pas des garanties au prochain lancer.","белгісіздікті кейінгі D6-ға қалдырыңыз. 0 сағ/0 алтын, 4 сағ/1 алтын және 8 сағ/2 алтын нәтижелерінің әрқайсысының ықтималдығы 1/3. Күтілетін шығын = (0 + 1 + 2) ÷ 3 = 1 алтын; күтілетін жөндеу уақыты = (0 + 4 + 8) ÷ 3 = 4 сағ. Бұл — орташа мәндер, келесі лақтыруға кепіл емес."],["Class discussion:","Discussion en classe :","Сыныптық талқылау:"],["Which constraint limited shipments? Who paid for the issue and who experienced the delay? What evidence, recovery deadline, cost-sharing agreement or supplier corrective-action plan would you negotiate? Compare actual decisions with alternatives; the game does not simulate the unchosen outcome.","Quelle contrainte a limité les livraisons ? Qui a payé et qui a subi le retard ? Quelles preuves, échéances de rétablissement, règles de partage des coûts ou actions correctives négocieriez-vous ? Comparez les décisions aux alternatives ; le jeu ne simule pas l’option non choisie.","Қандай шектеу жеткізілімді азайтты? Мәселеге кім төледі, кідірісті кім сезінді? Қандай дәлел, қалпына келтіру мерзімі, шығын бөлісу келісімі немесе жеткізушінің түзету жоспарын келісер едіңіз? Нақты шешімді баламамен салыстырыңыз; ойын таңдалмаған нәтижені модельдемейді."],["Final settlement is separate from Round 15 production.","Le règlement final est distinct de la production de la manche 15.","Қорытынды есеп 15-раунд өндірісінен бөлек."],["Settlement charges","Charges du règlement final","Қорытынды есеп шығындары"],["net settlement cash adjustments","ajustements nets du règlement final","қорытынды есептің таза ақша түзетулері"],["No new shipments are produced. Use the main ledger for final balances.","Aucune nouvelle livraison. Consultez le registre principal pour les soldes finaux.","Жаңа жеткізілім жасалмайды. Соңғы қалдықты негізгі есептен қараңыз."],["Decisions and events in this round","Décisions et événements de cette manche","Осы раундтағы шешімдер мен оқиғалар"],["Component 1","Composant 1","Бөлшек 1"],["Component 2","Composant 2","Бөлшек 2"],["Component 3","Composant 3","Бөлшек 3"],["Subassemblies","Sous-ensembles","Тораптар"],["Uninspected Titans","Titans non contrôlés","Тексерілмеген Титандар"],["Buffer","Stock intermédiaire","Аралық қор"],["Factory gold","Or de l’usine","Зауыт алтыны"],["capacity","capacité","қуат"],["h/unit","h/unité","сағ/өнім"],["Resume saved session","Reprendre la partie sauvegardée","Сақталған ойынды жалғастыру"],["Ironhold classroom","Classe Ironhold","Ironhold сабағы"],["Classroom session","Partie en classe","Сыныптық ойын"],["Runs in your browser · No account or server required for shared-screen play","Fonctionne dans le navigateur · Aucun compte ni serveur requis pour jouer sur écran partagé","Браузерде жұмыс істейді · Ортақ экранда ойнау үшін тіркелгі не сервер қажет емес"],["full factory view","vue complète de l’usine","зауыттың толық көрінісі"],["classroom reveal","présentation en classe","сыныптық көрсету"],["Guild dashboard","Tableau de bord de la guilde","Гильдия панелі"],["Session complete","Partie terminée","Ойын аяқталды"],["Early Dawn","Aube","Таң"],["Fires of Noon","Feux de midi","Түскі жалын"],["Twilight of Battle","Crépuscule","Ымырт"],["Cycle","Cycle","Цикл"],["teams","équipes","команда"],["rounds","manches","раунд"],["gold each","pièces chacune","алтыннан"],["Starting rule:","Règle initiale :","Бастапқы ереже:"],["gold per guild","pièces par guilde","алтын әр гильдияға"],["Sender must keep at least 1 gold.","L’émetteur doit conserver au moins 1 pièce.","Жіберушіде кемінде 1 алтын қалуы тиіс."],["exceptions are recorded against this round.","les exceptions sont enregistrées pour cette manche.","ерекшеліктер осы раундқа тіркеледі."],["gold adjustments and notes only.","ajustements d’or et notes uniquement.","тек алтын түзетулері мен ескертулер."],["Stage","Étape","Саты"],["Roll D","Lancer D","Лақтыру: D"],["production","production","өндіріс"],["procurement exception","incident d’approvisionnement","жабдықтау оқиғасы"],["corrective action","action corrective","түзету әрекеті"],["supplier attribution","attribution de l’origine","жеткізуші көзін анықтау"],["risk review","évaluation du risque","тәуекелді бағалау"],["Production","Production","Өндіріс"],["Procurement exception","Incident d’approvisionnement","Жабдықтау оқиғасы"],["Corrective action","Action corrective","Түзету әрекеті"],["Supplier attribution","Attribution de l’origine","Жеткізуші көзін анықтау"],["result","Résultat","Нәтиже"],["Your latest roll","Votre dernier lancer","Сіздің соңғы лақтыруыңыз"],["roll recorded.","lancer enregistré.","лақтыру тіркелді."],["rolls recorded","lancers enregistrés","лақтыру тіркелді"],["Last completed roll","Dernier lancer effectué","Соңғы аяқталған лақтыру"],["transferred this round","transférées cette manche","осы раундта берілді"],["total units","unités cumulées","жалпы өнім"],["Total units","Unités cumulées","Жалпы өнім"],["Queued downtime","Arrêt en attente","Кезектегі тоқтау"],["repair hours served this round","heures de réparation effectuées cette manche","осы раундта өтелген жөндеу сағаты"],["downtime served this round.","heures d’arrêt effectuées cette manche.","осы раундта өтелген тоқтау."],["risk reviews pending.","évaluations de risque en attente.","тәуекел талдауы күтілуде."],["analysis tasks pending","analyses en attente","талдау күтілуде"],["analysis task pending","analyse en attente","талдау күтілуде"],["outstanding","restantes","қалған"],["hours","heures","сағат"],["waiting","en attente","күтуде"],["Vendor:","Fournisseur :","Жеткізуші:"],["occurrences","incidents","оқиға"],["changes","changements","ауыстыру"],["change","changement","ауыстыру"],["Protected through round","Protection jusqu’à la manche","Қорғаныс осы раундқа дейін:"],["event 8 is rerolled.","l’incident 8 est relancé.","8-оқиға қайта лақтырылады."],["Team","Équipe","Команда"],["Base","Base","Негізгі"],["Repair hours","Heures de réparation","Жөндеу сағаттары"],["Rework hold","Blocage pour reprise","Қайта өңдеуге тоқтату"],["Yes","Oui","Иә"],["No","Non","Жоқ"],["Occurrence","Incident","Оқиға"],["vote","vote","дауыс"],["All decisions for","Toutes les décisions pour","Мына командалардың барлық шешімдері:"],["are complete. Predict the actual output before releasing it.","sont terminées. Prévoyez la sortie réelle avant de la libérer.","аяқталды. Берер алдында нақты өнімді болжаңыз."],["complete","terminée","аяқталды"],["approved in total.","approuvés au total.","барлығы мақұлданды."],["this round.","cette manche.","осы раундта."],["in total.","au total.","барлығы."],["gold across all guilds.","pièces dans l’ensemble des guildes.","барлық гильдияның алтыны."],["gold remaining across all guilds.","pièces restantes dans l’ensemble des guildes.","барлық гильдияда қалған алтын."],["already-paid repair hours remain outstanding.","heures de réparation déjà payées restent à effectuer.","төленген жөндеу сағаттары қалған."],["Master Guilds","Guildes maîtresses","Үздік гильдиялар"],["Master Guild","Guilde maîtresse","Үздік гильдия"],["analysis task(s) remain unresolved because bankruptcy ended play.","analyse(s) restent non résolues car la faillite a terminé le jeu.","банкроттық ойынды аяқтағандықтан талдау шешілмеді."],["The six guilds begin with","Les six guildes commencent avec","Алты гильдияның бастапқы мөлшері:"],["Total approved Titans:","Total de Titans approuvés :","Барлық мақұлданған Титандар:"],["good units transferred.","unités conformes transférées.","жарамды өнім берілді."],["good unit transferred.","unité conforme transférée.","жарамды өнім берілді."],["good units approved and shipped.","unités conformes approuvées et livrées.","жарамды өнім мақұлданып жеткізілді."],["good unit approved and shipped.","unité conforme approuvée et livrée.","жарамды өнім мақұлданып жеткізілді."],["no production die.","aucun dé de production.","өндіріс текшесі жоқ."],["repair hours served","heures de réparation effectuées","өтелген жөндеу сағаты"],["waiting for a complete input set; no dice or fine.","en attente d’un jeu complet de composants ; ni dé ni amende.","толық кіріс жиынтығы күтілуде; текше не айыппұл жоқ."],["Unknown cause: roll again until an applicable even cause is found.","Cause inconnue : relancez jusqu’à une cause paire applicable.","Себеп белгісіз: жарамды жұп себеп түскенше қайта лақтырыңыз."],["This cause does not apply here. Reroll without a charge.","Cette cause est inapplicable ici. Relancez sans frais.","Бұл себеп мұнда жарамсыз. Ақысыз қайта лақтырыңыз."],["This solution does not apply. Reroll; the selected procurement response is unchanged.","Cette solution est inapplicable. Relancez sans changer la réponse d’achat choisie.","Бұл шешім жарамсыз. Таңдалған сатып алу әрекетін өзгертпей қайта лақтырыңыз."],["Current vendor occurrence","Incident du fournisseur actuel","Қазіргі жеткізуші оқиғасы"],["Vendor changed. Protection covers the rest of this round through round","Fournisseur changé. La protection couvre cette manche et se poursuit jusqu’à la manche","Жеткізуші ауысты. Қорғаныс осы раундтан мына раундқа дейін:"],["Vendor vote:","Vote fournisseur :","Жеткізуші дауысы:"],["Vendor retained; occurrence count carries forward.","Fournisseur conservé ; le compteur d’incidents est maintenu.","Жеткізуші сақталды; оқиғалар саны жалғасады."],["chooses planned supplier corrective action","choisit une action corrective fournisseur planifiée","жеткізушінің жоспарлы түзету әрекетін таңдайды"],["chooses supplier risk review","choisit l’évaluation du risque fournisseur","жеткізуші тәуекелін бағалауды таңдайды"],["chooses a quality hold","choisit un blocage qualité","сапа бойынша тоқтатуды таңдайды"],["output held at zero; inputs retained. Repair assigned to","la sortie reste nulle ; composants conservés. Réparation attribuée à","өнім нөлде ұсталады; кірістер сақталады. Жөндеу мынаған жүктелді:"],["Rework detected at","Reprise détectée à","Қайта өңдеу анықталған орын:"],["Factory stopped: at least one guild has zero or negative gold. No Master Guild is awarded.","Usine arrêtée : au moins une guilde a un solde nul ou négatif. Aucun titre de guilde maîtresse.","Зауыт тоқтады: кемінде бір гильдияда нөл не теріс алтын. Үздік гильдия атағы берілмейді."],["Final settlement begins. No further production is permitted.","Le règlement final commence. Aucune production supplémentaire.","Қорытынды есеп басталды. Қосымша өндіріс рұқсат етілмейді."],["Ironhold defended: target met and all guilds survived.","Ironhold défendue : objectif atteint et toutes les guildes ont survécu.","Ironhold қорғалды: мақсат орындалды және барлық гильдия сақталды."],["Practice complete. Review shipments, gold and remaining repairs.","Entraînement terminé. Examinez livraisons, or et réparations restantes.","Жаттығу аяқталды. Жеткізілімді, алтынды және қалған жөндеуді қараңыз."],["The factory survived, but the shipment target was missed.","L’usine a survécu, mais l’objectif de livraison a été manqué.","Зауыт сақталды, бірақ жеткізу мақсаты орындалмады."],["gold charged","pièces facturées","алтын есептелді"],["gold","or","алтын"],["keep","conserver","қалдыру"],["and","et","және"],["round","manche","раунд"],["repair hours","heures de réparation","жөндеу сағаттары"],["due round","dû à la manche","мерзімі: раунд"],["next round, no gold charge","manche suivante, sans frais d’or","келесі раунд, алтын алынбайды"],["all guilds","toutes les guildes","барлық гильдия"],["transfers","transfère","аударады"],["from","de","кімнен:"],["to","vers","кімге:"],["Game Master downtime","Arrêt décidé par le maître du jeu","Жүргізуші қосқан тоқтау"],["solution","solution","шешім"],["origin","origine","себеп көзі"],["analysis","analyse","талдау"],["event","incident","оқиға"],["note","note","ескерту"],["downtime","arrêt","тоқтау"],["Choose a role before acting.","Choisissez un rôle avant d’agir.","Әрекет етпес бұрын рөл таңдаңыз."],["This action belongs to the Game Master or another guild.","Cette action appartient au maître du jeu ou à une autre guilde.","Бұл әрекет жүргізушіге не басқа гильдияға тиесілі."],["Virtual dice are unavailable. Enter a physical die result.","Les dés virtuels sont indisponibles. Saisissez un résultat physique.","Виртуалды текше қолжетімсіз. Нақты текше нәтижесін енгізіңіз."],["Record each of the three shop votes.","Enregistrez le vote de chacun des trois ateliers.","Үш цехтың әрқайсысының дауысын тіркеңіз."],["This game has ended.","Cette partie est terminée.","Бұл ойын аяқталды."],["Choose a guild.","Choisissez une guilde.","Гильдия таңдаңыз."],["Choose two different guilds.","Choisissez deux guildes différentes.","Екі бөлек гильдия таңдаңыз."],["Transfer a whole number from 1 to 1000 gold.","Transférez un nombre entier de 1 à 1000 pièces.","1–1000 аралығындағы бүтін алтын санын аударыңыз."],["The sending guild must retain at least 1 gold.","La guilde émettrice doit conserver au moins 1 pièce.","Жіберуші гильдияда кемінде 1 алтын қалуы тиіс."],["Enter a reason of 3–240 characters.","Saisissez un motif de 3 à 240 caractères.","3–240 таңбалық себеп енгізіңіз."],["Choose a supported exception.","Choisissez une exception prise en charge.","Қолдау көрсетілетін ерекшелікті таңдаңыз."],["Choose a guild or all guilds.","Choisissez une guilde ou toutes les guildes.","Бір гильдияны не барлық гильдияны таңдаңыз."],["Gold adjustment must be a nonzero whole number between -1000 and 1000.","L’ajustement doit être un entier non nul entre -1000 et 1000.","Алтын түзетуі -1000 мен 1000 арасында, нөл емес бүтін сан болуы тиіс."],["Next-round downtime is available only in rounds 1–14.","L’arrêt de la manche suivante n’est disponible qu’aux manches 1–14.","Келесі раунд тоқтауы тек 1–14-раундтарда қолжетімді."],["Choose 4, 8, 16 or 32 downtime hours.","Choisissez 4, 8, 16 ou 32 heures d’arrêt.","4, 8, 16 немесе 32 тоқтау сағатын таңдаңыз."],["A die is not expected.","Aucun dé n’est attendu.","Текше күтілмейді."],["A signal is not expected.","Aucune réponse n’est attendue.","Әрекет таңдауы күтілмейді."],["Choose a permitted signal.","Choisissez une réponse autorisée.","Рұқсат етілген әрекетті таңдаңыз."],["A vendor vote is not expected.","Aucun vote fournisseur n’est attendu.","Жеткізуші дауысы күтілмейді."],["Record all three shop votes.","Enregistrez les trois votes des ateliers.","Үш цехтың дауысын тіркеңіз."],["Output is not ready to release.","La production n’est pas prête à être libérée.","Өнім беруге дайын емес."],["Complete the round first.","Terminez d’abord la manche.","Алдымен раундты аяқтаңыз."],["There is no action to undo.","Aucune action à annuler.","Қайтарылатын әрекет жоқ."],["This is not a valid JSON save file.","Ce fichier n’est pas une sauvegarde JSON valide.","Бұл жарамды JSON сақтау файлы емес."],["This is not an Ironhold 3.0.0 save.","Cette sauvegarde n’est pas au format Ironhold 3.0.0.","Бұл Ironhold 3.0.0 сақтау файлы емес."],["Invalid or oversized game history.","Historique invalide ou trop volumineux.","Ойын тарихы жарамсыз не тым үлкен."],["Return to setup? Download a save first to keep this session.","Revenir à la préparation ? Téléchargez d’abord une sauvegarde pour conserver cette partie.","Баптауға оралу керек пе? Ойынды сақтау үшін алдымен көшірмені жүктеп алыңыз."]];
window.IronholdRuleLocales={"fr":"<p class=\"eyebrow\">GUILDES DES STEPPES · RÈGLES D’ACHATS</p><h2>Histoire et règles</h2><p>Dans cette fiction inspirée du Kazakhstan, six guildes construisent les Titans qui protègent Ironhold. Saryarqa forge les châssis (atelier 1), Altaï produit les moteurs (atelier 2), Zhetysu fabrique les armures (atelier 3), Shanyraq réalise le sous-assemblage, Tulpar l’assemblage final et Qyran le contrôle qualité. Ces guildes sont imaginaires, pas des organisations historiques.</p>\n<details open><summary>1. Objectif et préparation</summary><p>Chaque guilde commence avec 10 pièces d’or ; l’enseignant peut choisir de 1 à 1000 pièces avant le départ. Une manche représente une journée de 8 heures. La capacité complète est de 2 unités entières. Les cinq stocks intermédiaires commencent à zéro. Les matières premières sont illimitées sauf incidents fournisseur. Choisissez l’entraînement ou annoncez un objectif de 1 à 30 Titans approuvés pour l’ensemble de la partie.</p><p>Une mission réussit si les six guildes restent strictement au-dessus de zéro or et atteignent l’objectif après la manche 15 et son règlement final. Les guildes les plus riches partagent alors le titre de guilde maîtresse. Un solde nul ou négatif arrête le jeu. L’entraînement mesure production et survie sans victoire sur objectif. 30 est un maximum physique, pas un objectif validé en classe.</p><p>Cycles : Aube, manches 1–5 ; Feux de midi, 6–10 ; Crépuscule, 11–15. Toutes les guildes agissent à chaque manche ; les changements de cycle ne réinitialisent rien.</p></details>\n<details><summary>2. Étapes, capacité et stocks</summary><p>Étape 1 : ateliers 1 et 2. Étape 2 : atelier 3 et sous-assemblage. Étape 3 : assemblage final. Étape 4 : qualité. Résolvez les décisions dans cet ordre. Les équipes jumelées libèrent ensemble leurs sorties après leurs deux décisions.</p><p>Au début d’une manche, résolvez les analyses dues, puis effectuez au plus 8 heures de réparation par équipe. Une équipe en réparation ne lance ni dé de production ni dé d’incident ; sa capacité de base vaut 2. Sinon, avec un jeu complet de composants, lancez D6 : 1–3 donne une capacité de base de 1 ; 4–6 donne 2. Sans composants complets : ni lancer ni amende.</p><p>Capacité utilisable = max(0, capacité de base − heures de réparation effectuées ÷ 4). Sortie réelle = minimum de cette capacité et de chaque stock requis. Consommez une unité de chaque composant requis par unité conforme. Reportez le surplus. Les ateliers n’ont pas de contrainte quantitative d’entrée. Seules les unités approuvées par Qyran sont des livraisons. Une correction de 0 heure ne restaure pas l’unité perdue par un lancer partiel.</p><p>Les réparations immédiates sont effectuées avant la sortie de l’équipe. Les tickets futurs attendent leur échéance ; les heures sont servies en séquence, au plus 8 par équipe et par manche. Le jeu s’arrête avant chaque libération pour permettre une prévision en classe.</p></details>\n<details><summary>3. Incidents d’approvisionnement et réponses</summary><p>Un lancer partiel impose un D10. Impair : cause inconnue, relance. 2 : panne, toutes équipes. 4 : pièce défectueuse, uniquement sous-assemblage, assemblage final et qualité. 6 : désalignement, toutes équipes. 8 : matière première défectueuse, uniquement ateliers 1–3 hors protection fournisseur. 10 : panne majeure, toutes équipes. Relancez sans frais les causes inapplicables. Le 0 d’un dé physique signifie 10.</p><p>Flux normal : procédé local sain. Action corrective planifiée : choisir la solution et payer maintenant, réparer à la manche suivante. Évaluation du risque fournisseur : analyse D6 à la manche suivante. Blocage qualité : correction immédiate. Seules les causes 2 et 6 autorisent le choix planifié ou l’analyse. Les causes 4 et 10 imposent le blocage qualité. La cause 8 utilise le vote fournisseur. Une équipe sans composants est en attente. L’alerte elle-même ne coûte rien.</p><p>Analyse D6 : 1–2 = 0 h / 0 or ; 3–4 = 4 h / 1 or ; 5–6 = 8 h / 2 or. L’incident est ensuite clos. Une analyse décidée à la manche 15 est réglée après la production, avec son coût.</p></details>\n<details><summary>4. Réparation, reprise et coût</summary><p>D4 : 1 = arrêt et examen, causes 2 ou 6, 4 h / 1 or. 2 = analyse de cause racine, tout incident hors fournisseur, 8 h / 2 or. 3 = correction logicielle ou de pièce, causes 2 ou 6, 0 h / 0 or. 4 = reprise, uniquement pièce défectueuse, 8 h / 2 or facturés à l’origine. Relancez les solutions inapplicables. Les solutions 1–3 concernent l’équipe détectrice. Le blocage qualité est immédiat, l’action planifiée commence à la manche suivante ; une correction gratuite se clôt immédiatement.</p><p>La reprise bloque à zéro la sortie de l’équipe détectrice et conserve ses composants. Elle ne paie pas de frais supplémentaires. Origine au sous-assemblage : D6 1–3 désigne l’atelier 1, 4–6 l’atelier 2. À l’assemblage final : 1–3 désigne le sous-assemblage, 4–6 l’atelier 3. À la qualité : l’origine est l’assemblage final, sans dé. L’origine paie maintenant et effectue 8 heures dès la manche suivante.</p><p>Chaque ticket est payé une fois à son émission : 4 h = 1 or ; 8 h = 2 or ; changement fournisseur imposé, 32 h = 7 or. Quatre tickets distincts de 8 h coûtent 8 or, pas 7. Effectuer des heures déjà payées ne crée pas de seconde charge. Capacité partielle, manque de composants et alerte ne créent pas d’amendes distinctes.</p><p>La faillite est vérifiée après chaque charge résolue ou lot indivisible de charges. Les trois tickets d’un changement fournisseur sont émis ensemble. Les analyses dues constituent un lot d’ouverture de manche. Si le jeu s’arrête avant la libération d’une étape, aucune de ses sorties n’est transférée.</p></details>\n<details><summary>5. Vote fournisseur et protection</summary><p>Seule une cause 8 valide déclenche ce mécanisme. Comptez les occurrences du fournisseur actuel sur les trois ateliers. Aux occurrences 1 et 2, les trois ateliers votent : au moins deux voix pour changer imposent à chacun un ticket de 8 h / 2 or. Sinon, le fournisseur et le compteur sont conservés. L’atelier touché garde une capacité de base partielle de 1 cette manche et ne lance pas de D4 local.</p><p>La troisième occurrence impose le changement : 32 h / 7 or par atelier, sans charge volontaire supplémentaire. Réparations dès la manche suivante ; compteur remis à zéro à chaque changement. La protection commence immédiatement et couvre les cinq manches numérotées suivantes : changement en manche 4, protection jusqu’à 9, cause 8 possible en 10. Relancez cette cause pendant la protection. La production déjà effectuée n’est pas annulée.</p></details>\n<details><summary>6. Transferts d’or et exceptions enseignant</summary><p>Pendant une partie active, les guildes peuvent transférer un montant entier avec un accord enregistré. L’émetteur doit conserver au moins 1 or. Le transfert conserve l’or total mais modifie le classement des guildes. Négociez avant la charge : un transfert ne réanime pas une partie déjà arrêtée pour faillite.</p><p>Le maître du jeu peut ajouter ou retirer de l’or immédiatement, programmer un arrêt gratuit pour la manche suivante (manches 1–14 uniquement), ou enregistrer une consigne. Une note ne modifie pas les calculs. Chaque exception exige le nom de l’enseignant et une explication. Une pénalité ramenant un solde à zéro termine le jeu. Ces commandes partagées ne sont pas des comptes authentifiés.</p></details>\n<details><summary>7. Fin, sauvegarde et enseignement</summary><p>Après la manche 15, résolvez toutes les analyses différées avant le résultat. Les réparations déjà payées restant après la fin sont indiquées mais non refacturées. Aucune livraison supplémentaire. À chaque fin de cycle, discutez du goulet, de la valeur d’une alerte et de l’or local face à la production globale.</p><p>Enregistrer télécharge un historique JSON. Charger le rejoue et le valide ; les soldes modifiables ne sont pas acceptés directement. La sauvegarde du navigateur n’est pas une copie de sécurité. Annuler sert à corriger une saisie, jamais à relancer un mauvais résultat. Le CSV conserve la comptabilité équipe-manche et signale les sorties non libérées. Tous les dés, relances et votes sont conservés.</p><p>Modèle pédagogique simplifié : les défauts réduisent ou bloquent la production ; ni lots cachés défectueux, ni précision du contrôle, ni défauts récurrents ne sont modélisés. L’attribution aléatoire de l’origine sert au débat, pas à la traçabilité réelle. L’équilibre doit être testé en classe.</p></details>\n","kk":"<p class=\"eyebrow\">ДАЛА ГИЛЬДИЯЛАРЫ · САТЫП АЛУ ЕРЕЖЕЛЕРІ</p><h2>Оқиға мен ережелер</h2><p>Қазақстан мәдениетінен шабыт алған осы қиял әлемінде алты гильдия Ironhold қаласын қорғайтын Титандарды жасайды. Сарыарқа қаңқа соғады (1-цех), Алтай қозғалтқыш жасайды (2-цех), Жетісу сауыт дайындайды (3-цех), Шаңырақ тораптарды құрастырады, Тұлпар соңғы құрастыруды, Қыран сапа бақылауын атқарады. Бұлар тарихи ұйымдар емес, ойдан шығарылған гильдиялар.</p>\n<details open><summary>1. Мақсат және дайындық</summary><p>Әр гильдия әдепкіде 10 алтыннан бастайды; оқытушы ойын алдында 1–1000 алтын таңдай алады. Бір раунд — 8 сағаттық күн. Толық қуат — 2 бүтін өнім. Бес аралық қор нөлден басталады. Жеткізуші оқиғаларынан басқа жағдайда шикізат шексіз. Жаттығу режимін таңдаңыз немесе бүкіл ойынға 1–30 мақұлданған Титан мақсатын алдын ала белгілеңіз.</p><p>Миссия сәтті болуы үшін барлық алты гильдияда нөлден артық алтын қалып, 15-раунд пен қорытынды есептен кейін мақсат орындалуы керек. Сонда ең бай гильдиялар үздік гильдия атағын бөліседі. Алтын нөлге немесе теріс санға түссе, ойын тоқтайды. Жаттығу өнім мен өміршеңдікті көрсетеді, мақсат жеңісін бермейді. 30 жеткізілім — физикалық шек, сыныпта тексерілген мақсат емес.</p><p>Циклдер: Таң, 1–5-раунд; Түскі жалын, 6–10; Ымырт, 11–15. Барлық гильдия әр раундта әрекет етеді. Цикл ауысқанда ақша, қор не жөндеу нөлденбейді.</p></details>\n<details><summary>2. Сатылар, қуат және қорлар</summary><p>1-саты: 1 және 2-цех. 2-саты: 3-цех және торапты құрастыру. 3-саты: соңғы құрастыру. 4-саты: сапа бақылауы. Шешімдерді осы ретпен орындаңыз. Жұп командалар екі шешім де аяқталған соң өнімін бірге береді.</p><p>Раунд басында мерзімі жеткен талдауларды шешіп, әр командаға кезектегі жөндеудің ең көбі 8 сағатын өтетіңіз. Жөнделіп жатқан команда өндіріс те, оқиға текшесін де лақтырмайды; негізгі қуаты 2 болады. Басқа жағдайда толық кіріс жиынтығы бар команда D6 лақтырады: 1–3 — негізгі қуат 1; 4–6 — қуат 2. Толық жиынтық болмаса, текше де, айыппұл да жоқ.</p><p>Қолжетімді қуат = max(0, негізгі қуат − өтелген жөндеу сағаты ÷ 4). Нақты өнім — осы қуат пен қажетті кіріс қорларының ең аз мәні. Әр жарамды өнімге әр қажетті бөлшектен біреу жұмсалады. Артық қор келесі раундқа қалады. Цехтардың кірісі санмен шектелмейді. Тек Қыран мақұлдаған өнім жеткізілім саналады. Нөл сағаттық түзету ішінара лақтыруда жоғалған өнімді қалпына келтірмейді.</p><p>Шұғыл жөндеу команданың өнімі берілгенге дейін өтеледі. Болашақ тапсырмалар өз раундын күтеді. Сағаттар кезекпен, әр командаға бір раундта ең көбі 8 сағаттан өтеледі. Әр саты өнімін берер алдында сынып нәтижені болжай алады.</p></details>\n<details><summary>3. Жабдықтау оқиғалары және әрекеттер</summary><p>Ішінара өндіріс нәтижесінен кейін D10 қажет. Тақ сан: себеп белгісіз, қайта лақтыру. 2: машина ақауы, барлық команда. 4: ақаулы бөлшек, тек торапты құрастыру, соңғы құрастыру және сапа бақылауы. 6: машинаның тураланбауы, барлық команда. 8: ақаулы шикізат, тек жеткізуші қорғанысы жоқ 1–3-цехтар. 10: күрделі бұзылу, барлық команда. Жарамсыз себепті ақысыз қайта лақтырыңыз. Нақты текшедегі 0 — 10.</p><p>Қалыпты жабдықтау: жергілікті үдеріс дұрыс. Жоспарлы түзету: шешімді қазір таңдап, қазір төлеу, келесі раундта жөндеу. Жеткізуші тәуекелін бағалау: келесі раундта D6 талдауы. Сапа бойынша тоқтату: шұғыл түзету. Тек 2 және 6 себептерінде жоспарлы әрекет не тәуекел талдауын таңдауға болады. 4 және 10 себептері сапа тоқтатуын талап етеді. 8-себеп жеткізуші дауысын қолданады. Бөлшексіз команда күтеді. Ескерту үшін жеке ақы алынбайды.</p><p>D6 талдауы: 1–2 = 0 сағ / 0 алтын; 3–4 = 4 сағ / 1 алтын; 5–6 = 8 сағ / 2 алтын. Оқиға содан кейін жабылады. 15-раунд талдауы өндіріс біткен соң өз құнымен есептеледі.</p></details>\n<details><summary>4. Жөндеу, қайта өңдеу және шығын</summary><p>D4: 1 = тоқтатып зерттеу, 2 не 6 себептері, 4 сағ / 1 алтын. 2 = түпкі себепті талдау, жеткізушіден өзге кез келген оқиға, 8 сағ / 2 алтын. 3 = бағдарламаны не бөлшекті түзету, 2 не 6 себептері, 0 сағ / 0 алтын. 4 = қайта өңдеу, тек ақаулы бөлшек, себеп көзіне 8 сағ / 2 алтын. Жарамсыз шешімді қайта лақтырыңыз. 1–3 шешімдерін ақауды тапқан команда орындайды. Сапа тоқтатуы — дереу, жоспарлы әрекет — келесі раундта. Тегін түзету бірден жабылады.</p><p>Қайта өңдеу ақауды тапқан команданың өнімін нөлде ұстап, кіріс бөлшектерін сақтайды. Бұл команда қосымша жөндеу ақысын төлемейді. Тораптағы ақау көзі: D6 1–3 — 1-цех, 4–6 — 2-цех. Соңғы құрастыруда: 1–3 — торапты құрастыру, 4–6 — 3-цех. Сапа бақылауында: себеп көзі — соңғы құрастыру, текше қажет емес. Себеп көзі қазір төлеп, келесі раундтан 8 сағат өтейді.</p><p>Әр тапсырма берілгенде бір рет төленеді: 4 сағ = 1 алтын; 8 сағ = 2; жеткізушіні мәжбүрлі ауыстыру, 32 сағ = 7. Төрт бөлек 8 сағаттық тапсырма 7 емес, 8 алтын тұрады. Төленген сағатты өтеу қайта шығын туғызбайды. Ішінара қуат, бөлшек тапшылығы және ескерту жеке айыппұл әкелмейді.</p><p>Әр шешілген шығыннан немесе бөлінбейтін шығындар тобынан кейін банкроттық тексеріледі. Жеткізуші ауысуының үш төлемі бірге енгізіледі. Мерзімі жеткен талдаулар раунд басындағы бір топ ретінде шешіледі. Саты өнімі берілмей тұрып ойын аяқталса, сол сатыдан өнім берілмейді.</p></details>\n<details><summary>5. Жеткізуші дауысы және қорғаныс</summary><p>Бұл ережені тек жарамды 8-себеп іске қосады. Қазіргі жеткізушінің оқиғаларын үш цех бойынша бірге санаңыз. 1 және 2-оқиғада үш цех дауыс береді: кемінде екі ауыстыру дауысы әр цехқа 8 сағ / 2 алтын тапсырмасын береді. Әйтпесе жеткізуші мен санау сақталады. Зардап шеккен цехтың осы раундтағы негізгі қуаты 1 болып қалады; жергілікті D4 лақтыруы жоқ.</p><p>Үшінші оқиға ауыстыруды міндеттейді: әр цехқа 32 сағ / 7 алтын, ерікті ауыстырудың қосымша ақысы жоқ. Жөндеу келесі раундта басталады. Әр ауыстыруда санау нөлденеді. Қорғаныс бірден басталып, келесі бес нөмірленген раундты қамтиды: 4-раундта ауысса, 9-раундқа дейін қорғайды; 8-себеп 10-раундта қайта мүмкін. Қорғаныс кезінде бұл себеп қайта лақтырылады. Бұрын жасалған өндіріс кері қайтарылмайды.</p></details>\n<details><summary>6. Алтын аударымдары және оқытушы ерекшеліктері</summary><p>Белсенді ойында гильдиялар келісімді жазып, бүтін алтын сомасын аудара алады. Жіберушіде кемінде 1 алтын қалуы тиіс. Аударым жалпы алтынды сақтайды, бірақ бай гильдия рейтингін өзгертеді. Шығынға дейін келісіңіз: аударым банкроттықтан аяқталған ойынды қайта жандандырмайды.</p><p>Жүргізуші алтынды дереу қоса не шегере алады, келесі раундқа тегін тоқтау қоса алады (тек 1–14-раундтарда), немесе нұсқау жаза алады. Ескерту есептеулерді өзгертпейді. Әр ерекшелікке оқытушы аты мен түсініктеме қажет. Айыппұл қалдықты нөлге түсірсе, ойын аяқталады. Бұл ортақ экран басқаруы, қорғалған жеке тіркелгілер емес.</p></details>\n<details><summary>7. Аяқтау, сақтау және оқыту</summary><p>15-раундтан кейін нәтиже анықталмас бұрын барлық кейінге қалған талдауды шешіңіз. Ойыннан кейін қалған, төленген жөндеу сағаттары көрсетіледі, бірақ қайта төленбейді. Қосымша жеткізілім болмайды. Цикл соңында тар орынды, ескертудің құнын және жергілікті алтын мен зауыт өнімінің арақатынасын талқылаңыз.</p><p>Сақтау JSON тарихын жүктейді. Жүктеу оны қайта орындап тексереді; өзгертілетін қалдықтарға тікелей сенбейді. Браузердегі автоматты сақтау — сақтық көшірме емес. Қайтару тек енгізу қатесін түзетуге арналған, қолайсыз нәтижені қайта лақтыруға емес. CSV команда-раунд есебін сақтап, берілмеген өнімді белгілейді. Барлық текше, қайта лақтыру және дауыс тарихта қалады.</p><p>Бұл жеңілдетілген оқу моделі: ақау өнімді азайтады не тоқтатады; жасырын ақаулы партиялар, тексеру дәлдігі және қайталанатын ақаулар есептелмейді. Себеп көзін кездейсоқ анықтау нақты қадағалау емес, талқылау құралы. Теңгерімді сыныпта тексеру керек.</p></details>\n"};
(function(){
'use strict';
const entries=window.IronholdLocaleData, rules=window.IronholdRuleLocales;
const table=new Map(entries.map(([en,fr,kk])=>[en,{fr,kk}]));
const escaped=x=>x.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
const pattern=new RegExp('(?<![\\p{L}])(?:'+[...table.keys()].sort((a,b)=>b.length-a.length).map(escaped).join('|')+')(?![\\p{L}])','gu');
let language='en';try{const saved=localStorage.getItem('ironhold-language');if(['en','fr','kk'].includes(saved))language=saved;}catch{}
const source=new WeakMap(),attributes=new WeakMap();
const dynamic=window.IronholdLocalePatterns.map(([re,fr,kk])=>({re:new RegExp(re,'g'),fr,kk}));
function text(value,lang=language){if(lang==='en')return value;const held=[];let out=value;for(const p of dynamic)out=out.replace(p.re,(...args)=>{const translated=p[lang].replace(/\$(\d+)/g,(_,n)=>args[Number(n)]);const token='\uE000'+held.length+'\uE001';held.push(translated);return token;});out=out.replace(pattern,key=>table.get(key)?.[lang]||key);return out.replace(/\uE000(\d+)\uE001/g,(_,n)=>held[n]);}
const skip=el=>!el||el.closest('script,style,textarea,input,[translate="no"],[data-rules-localized]');
const ruleRoot=document.querySelector('#rules-view .rules');rules.en=ruleRoot.innerHTML;
function setRules(el){if(el.dataset.rulesLocalized!==language){el.innerHTML=rules[language];el.dataset.rulesLocalized=language;}}
function apply(){observer.disconnect();document.documentElement.lang=language;
 setRules(ruleRoot);
 const common=document.querySelector('#guild-workspace>details');if(common){let content=common.querySelector('[data-rules-localized]');if(!content){const summary=common.querySelector('summary');common.replaceChildren(summary);content=document.createElement('div');common.append(content);}setRules(content);}
 const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;
 while(node=walker.nextNode()){if(skip(node.parentElement)||!node.nodeValue.trim())continue;const old=source.get(node),raw=old&&old.last===node.nodeValue?old.raw:node.nodeValue,out=text(raw);if(node.nodeValue!==out)node.nodeValue=out;source.set(node,{raw,last:out});}
 document.querySelectorAll('[placeholder],[title],[aria-label],img[alt]').forEach(el=>{if(skip(el))return;let saved=attributes.get(el)||{};for(const key of ['placeholder','title','aria-label','alt']){if(!el.hasAttribute(key))continue;const current=el.getAttribute(key),old=saved[key],raw=old&&old.last===current?old.raw:current,out=text(raw);if(out!==current)el.setAttribute(key,out);saved[key]={raw,last:out};}attributes.set(el,saved);});
 document.querySelectorAll('[data-language]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.language===language)));
 document.title=text('Ironhold · Steppe Guilds');observer.observe(document.body,{subtree:true,childList:true,characterData:true});
}
const observer=new MutationObserver(apply);
function setLanguage(lang){if(!['en','kk','fr'].includes(lang))return;language=lang;try{localStorage.setItem('ironhold-language',lang);}catch{}apply();}
document.querySelectorAll('[data-language]').forEach(b=>b.onclick=()=>setLanguage(b.dataset.language));
window.IronholdLocale={text,setLanguage,apply,get language(){return language;}};
const originalConfirm=window.confirm.bind(window);window.confirm=message=>originalConfirm(text(message));
apply();
})();
